// Üç giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in /kod komutlarında alanlar doğrudan gelir.
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body || {}) : j;

const chat_id = govde.chat_id ? String(govde.chat_id) : '';
let islem = String(govde.islem || govde.komut || '').trim().toLowerCase();
let baslik = String(govde.baslik || '').trim();
let kod = String(govde.kod || '');
let dil = String(govde.dil || '').trim().toLowerCase();
let etiket = String(govde.etiket || '').trim();
let q = String(govde.q || govde.ara || '').trim();
let id = Number(govde.id) || 0;

// Telegram tarafı tek bir "metin" alanı yollar; biçimi komuta göre çözülür.
const metin = String(govde.metin || '').trim();
if (metin) {
  if (islem === 'kaydet') {
    const satirlar = metin.split(/\r?\n/);
    if (satirlar.length > 1) {
      baslik = satirlar[0].trim();
      kod = satirlar.slice(1).join('\n').trim();
    } else if (metin.includes('|')) {
      baslik = metin.slice(0, metin.indexOf('|')).trim();
      kod = metin.slice(metin.indexOf('|') + 1).trim();
    } else {
      baslik = metin;
      kod = '';
    }
    // "Başlık #docker #bash" → etiketler başlıktan ayıklanır
    const etiketler = (baslik.match(/#[\wğüşıöçĞÜŞİÖÇ.-]+/g) || []).map((x) => x.slice(1));
    if (etiketler.length) {
      etiket = etiketler.join(',');
      baslik = baslik.replace(/#[\wğüşıöçĞÜŞİÖÇ.-]+/g, '').replace(/\s+/g, ' ').trim();
    }
  } else if (islem === 'getir' || islem === 'sil') {
    id = Number((metin.match(/#?(\d+)/) || [])[1]) || 0;
  } else {
    q = metin;
  }
}

if (!islem) {
  islem = kod ? 'kaydet' : id ? 'getir' : q ? 'ara' : 'liste';
}

return [{ json: { islem, baslik, kod, dil, etiket, q, id, chat_id, webhooktan } }];

// Kaydet / ara / getir / sil işlemlerini uygular.
// Okuma zinciri hata verdiyse: dosya bozuk/erişilemez ise çalışma durdurulur —
// aksi hâlde kasa boş sanılıp üzerine yazılır ve tüm parçacıklar kaybolur.
const okuHata = $('Parçacıkları Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Parçacıkları Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('parcacikalar.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const istek = $('İsteği Al (Kod)').first().json;
const okunan = $input.first().json || {};
const ham = (okunan.data && okunan.data.parcacikalar) || okunan.parcacikalar || [];
const parcacikalar = (Array.isArray(ham) ? ham : []).map((p) => ({ ...p }));

const EN_UZUN = 8000;
const simdi = () => new Date().toISOString();
const etiketListesi = (s) => String(s || '').split(/[,\s]+/).map((x) => x.replace(/^#/, '').trim().toLowerCase()).filter(Boolean);
const ozetSatir = (p) => '#' + p.id + ' ' + p.baslik + (p.dil ? ' [' + p.dil + ']' : '') +
  ((p.etiketler && p.etiketler.length) ? ' (' + p.etiketler.join(', ') + ')' : '');
const ilkSatir = (p) => String(p.kod || '').split(/\r?\n/)[0].slice(0, 70);

// Puanlı arama: başlık > etiket/dil > kod içi. Eşitlikte çok kullanılan önde.
const ara = (q) => {
  const kelimeler = q.toLowerCase().split(/\s+/).filter(Boolean);
  return parcacikalar
    .map((p) => {
      const baslik = String(p.baslik || '').toLowerCase();
      const etiketler = (p.etiketler || []).join(' ').toLowerCase();
      const dil = String(p.dil || '').toLowerCase();
      const kod = String(p.kod || '').toLowerCase();
      let puan = 0;
      for (const k of kelimeler) {
        if (baslik.includes(k)) puan += 3;
        if (etiketler.includes(k) || dil === k) puan += 2;
        if (kod.includes(k)) puan += 1;
      }
      return { p, puan };
    })
    .filter((x) => x.puan > 0)
    .sort((a, b) => b.puan - a.puan || (Number(b.p.kullanim) || 0) - (Number(a.p.kullanim) || 0))
    .map((x) => x.p);
};

let mesaj = '';
let telegramText = '';
let sonuc = null;
let yazilsin = false;
let hata = false;

if (istek.islem === 'kaydet') {
  if (!istek.baslik || !istek.kod) {
    hata = true;
    mesaj = 'Kullanım: başlık ve kod zorunlu.\nTelegram: /kodkaydet Başlık\n(ikinci satırdan itibaren kod)\nWebhook: {"baslik":"...","kod":"..."}';
    telegramText = esc(mesaj);
  } else {
    const id = parcacikalar.reduce((mx, p) => Math.max(mx, Number(p.id) || 0), 0) + 1;
    const kod = istek.kod.length > EN_UZUN ? istek.kod.slice(0, EN_UZUN) + '\n… (kırpıldı)' : istek.kod;
    const kayit = {
      id,
      baslik: istek.baslik.slice(0, 120),
      dil: istek.dil || '',
      etiketler: etiketListesi(istek.etiket),
      kod,
      olusturulma: simdi(),
      kullanim: 0,
      sonKullanim: null,
    };
    parcacikalar.push(kayit);
    yazilsin = true;
    sonuc = kayit;
    mesaj = '📎 Kaydedildi: ' + ozetSatir(kayit) + '\nGetirmek için: /kodgetir ' + id;
    telegramText = esc(mesaj);
  }
} else if (istek.islem === 'getir') {
  const p = parcacikalar.find((x) => Number(x.id) === Number(istek.id));
  if (!p) {
    hata = true;
    mesaj = '#' + istek.id + ' bulunamadı. /kod ile arayın.';
    telegramText = esc(mesaj);
  } else {
    p.kullanim = (Number(p.kullanim) || 0) + 1;
    p.sonKullanim = simdi();
    yazilsin = true;
    sonuc = p;
    mesaj = ozetSatir(p) + '\n\n' + p.kod;
    telegramText = '📎 <b>' + esc(p.baslik) + '</b>\n<pre><code>' + esc(p.kod) + '</code></pre>';
  }
} else if (istek.islem === 'sil') {
  const p = parcacikalar.find((x) => Number(x.id) === Number(istek.id));
  if (!p) {
    hata = true;
    mesaj = '#' + istek.id + ' bulunamadı.';
  } else {
    parcacikalar.splice(parcacikalar.indexOf(p), 1);
    yazilsin = true;
    mesaj = '🗑 Silindi: ' + ozetSatir(p);
  }
  telegramText = esc(mesaj);
} else if (istek.islem === 'ara' && istek.q) {
  const bulunan = ara(istek.q);
  sonuc = bulunan;
  if (bulunan.length === 0) {
    mesaj = '"' + istek.q + '" için parçacık yok. Kaydetmek için: /kodkaydet Başlık ⏎ kod';
  } else {
    mesaj = '📎 "' + istek.q + '" (' + bulunan.length + ' sonuç)\n' +
      bulunan.slice(0, 5).map((p) => ozetSatir(p) + '\n   ' + ilkSatir(p)).join('\n') +
      '\n\nTamamı için: /kodgetir <numara>';
  }
  telegramText = esc(mesaj);
} else {
  // liste
  sonuc = parcacikalar;
  if (parcacikalar.length === 0) {
    mesaj = 'Kasa boş. Kaydetmek için: /kodkaydet Başlık ⏎ kod';
  } else {
    const sirali = [...parcacikalar].sort((a, b) => (Number(b.kullanim) || 0) - (Number(a.kullanim) || 0) || Number(b.id) - Number(a.id));
    mesaj = '📎 Kasada ' + parcacikalar.length + ' parçacık:\n' +
      sirali.slice(0, 10).map((p) => ozetSatir(p)).join('\n') +
      (parcacikalar.length > 10 ? '\n…ve ' + (parcacikalar.length - 10) + ' tane daha' : '') +
      '\n\nAramak için: /kod <kelime>';
  }
  telegramText = esc(mesaj);
}

return [{ json: {
  parcacikalar,
  yazilsin,
  hata,
  mesaj,
  telegramText,
  sonuc,
  chat_id: istek.chat_id,
  webhooktan: istek.webhooktan,
  islem: istek.islem,
} }];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider (kod bloğu HTML olarak).
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.telegramText || j.mesaj).slice(0, 3900) } }];

// Dosyaya yalnızca parçacık listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { parcacikalar: j.parcacikalar } }];

// GET /webhook/kodlar — arama ve tek parçacık getirme (terminalden kullanım için).
//   ?ara=docker      → eşleşen parçacıklar (JSON)
//   ?id=3            → tek parçacık (JSON)
//   ?id=3&sade=1     → yalnızca kodun kendisi (düz metin)
const sorgu = $('Parçacık Listesi (Webhook GET)').first().json.query || {};
const okuHata = $('Parçacıkları Oku (Liste)').first().json.error;
const cikarHata = $('Parçacıkları Çıkar (Liste)').first().json.error;
if (okuHata || cikarHata) {
  const m = String((okuHata && (okuHata.message || okuHata)) || (cikarHata && (cikarHata.message || cikarHata)));
  return [{ json: { sade: false, govde: { hata: 'parcacikalar.json okunamadı: ' + m } } }];
}

const j = $input.first().json || {};
const ham = (j.data && j.data.parcacikalar) || j.parcacikalar || [];
const parcacikalar = Array.isArray(ham) ? ham : [];

const id = Number(sorgu.id) || 0;
const q = String(sorgu.ara || sorgu.q || '').trim().toLowerCase();
const sade = String(sorgu.sade || '') === '1';

if (id) {
  const p = parcacikalar.find((x) => Number(x.id) === id);
  if (!p) return [{ json: { sade, govde: sade ? '' : { hata: '#' + id + ' bulunamadı' } } }];
  return [{ json: { sade, govde: sade ? String(p.kod || '') : p } }];
}

const kelimeler = q.split(/\s+/).filter(Boolean);
const bulunan = kelimeler.length === 0 ? parcacikalar : parcacikalar
  .map((p) => {
    const alan = [p.baslik, p.dil, (p.etiketler || []).join(' '), p.kod].join('\n').toLowerCase();
    let puan = 0;
    for (const k of kelimeler) if (alan.includes(k)) puan += 1;
    return { p, puan };
  })
  .filter((x) => x.puan > 0)
  .sort((a, b) => b.puan - a.puan)
  .map((x) => x.p);

return [{ json: { sade, govde: sade ? bulunan.map((p) => p.kod).join('\n\n') : bulunan } }];

// ?sade=1 verildiyse yanıt düz metin olur (curl ... | pbcopy için).
const j = $input.first().json;
return j.sade ? [{ json: j }] : [];

// Varsayılan yanıt: JSON.
const j = $input.first().json;
return j.sade ? [] : [{ json: j }];
